import{_ as a,a as t,c as n,ac as l}from"./chunks/framework.BSuaGltH.js";const b=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 143 A walk through the woods","description":"学习 现在完成时与将来时被动，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 143 A walk through the woods","description":"学习 现在完成时与将来时被动，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 现在完成时与将来时被动，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 142 Someone invited Sally ... Sally was invited ...","link":"/life/english/new-concept/book-1/unit-06/lesson-142"},"next":{"text":"第一册：英语初阶 · Lesson 144 He hasn't been served yet. He will be served soon.","link":"/life/english/new-concept/book-1/unit-06/lesson-144"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 142 Someone invited Sally ... Sally was invited ...","link":"/life/english/new-concept/book-1/unit-06/lesson-142"},"next":{"text":"第一册：英语初阶 · Lesson 144 He hasn't been served yet. He will be served soon.","link":"/life/english/new-concept/book-1/unit-06/lesson-144"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-06/lesson-143.md","filePath":"life/english/new-concept/book-1/unit-06/lesson-143.md"}`),o={name:"life/english/new-concept/book-1/unit-06/lesson-143.md"};function s(i,e,r,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[l('<h1 id="第一册-英语初阶-·-lesson-143-a-walk-through-the-woods" tabindex="-1">第一册：英语初阶 · Lesson 143 A walk through the woods <a class="header-anchor" href="#第一册-英语初阶-·-lesson-143-a-walk-through-the-woods" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 143 A walk through the woods&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元 6</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-144">配套课 Lesson 144</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>描述环境变化与待完成的工作 本课要掌握现在完成时与将来时被动，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。先根据情境判断为什么要这样问或这样说，再看语言形式。</p><p>本课为情景学习；完成后进入相邻偶数课进行句型迁移。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>wood</td><td>/wʊd/</td><td>n.</td><td>树林；木材</td><td>walk through the woods</td></tr><tr><td>litter</td><td>/ˈlɪtə/</td><td>n.</td><td>散落垃圾</td><td>pick up litter</td></tr><tr><td>cover</td><td>/ˈkʌvə/</td><td>v.</td><td>覆盖</td><td>cover the ground</td></tr><tr><td>plant</td><td>/plɑːnt/</td><td>v.</td><td>种植</td><td>plant trees</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>has been cleaned — 已被清理</li><li>will be planted — 将被种植</li></ul><h2 id="语法讲解-现在完成时与将来时被动" tabindex="-1">语法讲解：现在完成时与将来时被动 <a class="header-anchor" href="#语法讲解-现在完成时与将来时被动" aria-label="Permalink to &quot;语法讲解：现在完成时与将来时被动&quot;">​</a></h2><p>现在完成时被动为 have/has been + 过去分词，将来时被动为 will be + 过去分词。have/has 仍要与主语一致，been 不可漏；will 后用原形 be，不用 been。先判断是否被动，再判断完成或将来，不能把两种结构拼成 will been。表达“树木已被种下”与“明天将被种下”时，动作对象相同而时间不同。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The path has been cleared of fallen branches.</p></blockquote><p>小路上的落枝已经被清理了。</p><p>The path 是清理对象，has been cleared 为现在完成时被动；of fallen branches 说明被清除的东西。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>has been cleared 不能省略 been；will be planted 中 be 不写成 been。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“The path has been cleared of fallen branches.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The path has been cleared of fallen branches. New trees will be planted beside the stream.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“描述环境变化与待完成的工作”写两至三句，再读给同伴听。至少使用一次现在完成时与将来时被动，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>The path 是清理对象，has been cleared 为现在完成时被动；of fallen branches 说明被清除的东西。 New trees 是被种植对象，will be planted 为将来时被动；beside the stream 表未来种植位置。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补 be 的形式：The path has ___ cleared.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> been</p><p><strong>解析：</strong> 按本课规则判断：现在完成时被动为 have/has been + 过去分词，将来时被动为 will be + 过去分词。have/has 仍要与主语一致，been 不可漏；will 后用原形 be，不用 been。先判断是否被动，再判断完成或将来，不能把两种结构拼成 will been。表达“树木已被种下”与“明天将被种下”时，动作对象相同而时间不同。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“小路上的落枝已经被清理了。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The path has been cleared of fallen branches.</p><p><strong>解析：</strong> The path 是清理对象，has been cleared 为现在完成时被动；of fallen branches 说明被清除的东西。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：New trees will be planted beside the stream.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 小溪旁将种上新树。</p><p><strong>解析：</strong> New trees 是被种植对象，will be planted 为将来时被动；beside the stream 表未来种植位置。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：现在完成时与将来时被动。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-06/lesson-142">上一课</a> · <a href="/life/english/new-concept/book-1/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-06/lesson-144">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const u=a(o,[["render",s]]);export{b as __pageData,u as default};
